package com.sal7one.tvtestproject.receiver.media

import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Assert.fail
import org.junit.Test
import java.io.ByteArrayOutputStream
import java.util.Random

class H264ConfigTest {
    @Test fun libx264HighProfileSpsHasActual1080Crop() {
        // Host-generated by libx264 from a 1920x1080 yuv420p frame; no device or bundled clip.
        val nal = hex("67640028acd940780227e5c044000003000400000300f03c60c658")
        val dimensions = H264Config.parseSps(nal)
        assertEquals(1920, dimensions.codedWidth)
        assertEquals(1088, dimensions.codedHeight)
        assertEquals(1920, dimensions.width)
        assertEquals(1080, dimensions.height)
        assertEquals(100, dimensions.profileIdc)
    }

    @Test fun libx264ParameterSetsProduceAvccAndAnnexBCsd() {
        val nal = hex("67640028acd940780227e5c044000003000400000300f03c60c658")
        val picture = hex("68ebe3cb22c0")
        val config = H264Config.parseAvcc(avcc(listOf(nal), listOf(picture)))
        assertEquals(1080, config.height)
        assertArrayEquals(annexB(listOf(nal)), H264Config.parameterSetsToAnnexB(config.sps))
        assertArrayEquals(annexB(listOf(picture)), H264Config.parameterSetsToAnnexB(config.pps))
    }

    @Test fun baselineDimensionsInclude1088To1080Crop() {
        val dimensions = H264Config.parseSps(sps(widthMbs = 120, heightMapUnits = 68, cropBottom = 4))
        assertEquals(1920, dimensions.width)
        assertEquals(1080, dimensions.height)
        assertEquals(1088, dimensions.codedHeight)
        assertEquals(8, dimensions.cropBottom)
    }

    @Test fun interlacedCropUsesFrameFactor() {
        val dimensions = H264Config.parseSps(sps(widthMbs = 45, heightMapUnits = 15, frameOnly = false, cropBottom = 2))
        assertEquals(720, dimensions.width)
        assertEquals(480, dimensions.codedHeight)
        assertEquals(472, dimensions.height)
    }

    @Test fun highProfile422UsesDifferentVerticalCropUnit() {
        val dimensions = H264Config.parseSps(sps(profile = 122, chroma = 2, cropLeft = 1, cropTop = 1, cropBottom = 3))
        assertEquals(638, dimensions.width)
        assertEquals(476, dimensions.height)
        assertEquals(2, dimensions.cropLeft)
        assertEquals(1, dimensions.cropTop)
    }

    @Test fun monochromeAndSeparateColourPlaneUseLumaCropUnits() {
        for (nal in listOf(sps(profile = 100, chroma = 0, cropRight = 3),
            sps(profile = 244, chroma = 3, separatePlane = true, cropRight = 3))) {
            assertEquals(637, H264Config.parseSps(nal).width)
        }
    }

    @Test fun highProfileScalingMatrixAndPocTypeOneAreConsumed() {
        val dimensions = H264Config.parseSps(sps(profile = 100, scalingMatrix = true, pocType = 1))
        assertEquals(640, dimensions.width)
        assertEquals(480, dimensions.height)
    }

    @Test fun vuiWithEmulationPreventionAndHrdIsConsumed() {
        val nal = sps(vui = true)
        assertTrue(nal.indices.any { it >= 2 && nal[it - 2] == 0.toByte() && nal[it - 1] == 0.toByte() && nal[it] == 3.toByte() })
        assertEquals(480, H264Config.parseSps(nal).height)
    }

    @Test fun cropOutsidePictureIsRejected() {
        rejects { H264Config.parseSps(sps(widthMbs = 1, cropLeft = 8)) }
        rejects { H264Config.parseSps(sps(heightMapUnits = 1, cropBottom = 8)) }
    }

    @Test fun everyTruncatedSpsIsRejected() {
        val nal = sps(vui = true)
        for (size in 0 until nal.size) rejects { H264Config.parseSps(nal.copyOf(size)) }
    }

    @Test fun malformedRbspAndUnboundedGolombAreRejected() {
        rejects { H264Config.parseSps(byteArrayOf(0x67, 66, 0, 30, 0, 0, 0, 0, 0)) }
        rejects { H264Config.parseSps(sps() + byteArrayOf(0)) }
        rejects { H264Config.parseSps(sps() + byteArrayOf(0, 0, 3)) }
        rejects { H264Config.parseSps(sps() + byteArrayOf(0, 0, 3, 4)) }
        rejects { H264Config.parseSps(sps().also { it[2] = 1 }) }
    }

    @Test fun allValidLengthSizesAreRetained() {
        for (size in listOf(1, 2, 4)) {
            val config = H264Config.parseAvcc(avcc(lengthSize = size))
            assertEquals(size, config.nalLengthSize)
            assertEquals(640, config.width)
            assertEquals(480, config.height)
        }
    }

    @Test fun multipleParameterSetsArePreservedAndPpsSelectsDimensions() {
        val sets = listOf(sps(id = 0), sps(id = 1, widthMbs = 80, heightMapUnits = 45))
        val config = H264Config.parseAvcc(avcc(sets, listOf(pps(id = 7, spsId = 1), pps(id = 8, spsId = 0))))
        assertEquals(1280, config.width)
        assertEquals(720, config.height)
        assertEquals(2, config.sps.size)
        assertEquals(2, config.pps.size)
        assertArrayEquals(sets[0], config.sps[0])
        assertArrayEquals(sets[1], config.sps[1])
    }

    @Test fun parsedParameterSetsDoNotAliasInput() {
        val payload = avcc()
        val config = H264Config.parseAvcc(payload)
        val saved = config.sps.first().copyOf()
        payload.fill(0)
        assertArrayEquals(saved, config.sps.first())
        val source = sps()
        val copied = H264Config.fromParameterSets(listOf(source), listOf(pps()))
        source.fill(0)
        assertEquals(640, H264Config.parseSps(copied.sps.first()).width)
    }

    @Test fun everyTruncatedAvccIsRejected() {
        val payload = avcc()
        for (size in 0 until payload.size) rejects { H264Config.parseAvcc(payload.copyOf(size)) }
    }

    @Test fun invalidAvccHeaderAndReservedLengthSizeAreRejected() {
        for ((index, value) in listOf(0 to 2, 4 to 0xfb, 4 to 0x03, 4 to 0xfe, 5 to 0x01)) {
            val payload = avcc()
            payload[index] = value.toByte()
            rejects { H264Config.parseAvcc(payload) }
        }
    }

    @Test fun zeroAndOversizedParameterSetLengthsAreRejected() {
        for ((high, low) in listOf(0 to 0, 0xff to 0xff)) {
            val payload = avcc()
            payload[6] = high.toByte()
            payload[7] = low.toByte()
            rejects { H264Config.parseAvcc(payload) }
        }
    }

    @Test fun missingWrongAndDuplicateParameterSetsAreRejected() {
        rejects { H264Config.parseAvcc(avcc(emptyList(), listOf(pps()))) }
        rejects { H264Config.parseAvcc(avcc(listOf(sps()), emptyList())) }
        rejects { H264Config.parseAvcc(avcc(listOf(pps()), listOf(pps()))) }
        rejects { H264Config.parseAvcc(avcc(listOf(sps()), listOf(sps()))) }
        rejects { H264Config.parseAvcc(avcc(listOf(sps(), sps()), listOf(pps()))) }
        rejects { H264Config.parseAvcc(avcc(listOf(sps()), listOf(pps(), pps()))) }
        rejects { H264Config.parseAvcc(avcc(listOf(sps()), listOf(pps(spsId = 3)))) }
    }

    @Test fun highProfileExtensionWithoutAuxiliarySpsIsAccepted() {
        val payload = avcc(listOf(sps(profile = 100)), listOf(pps())) +
            byteArrayOf(0xfd.toByte(), 0xf8.toByte(), 0xf8.toByte(), 0)
        assertEquals(640, H264Config.parseAvcc(payload).width)
    }

    @Test fun trailingAndTruncatedExtensionsAreRejected() {
        rejects { H264Config.parseAvcc(avcc() + byteArrayOf(0)) }
        val high = avcc(listOf(sps(profile = 100)), listOf(pps()))
        rejects { H264Config.parseAvcc(high + byteArrayOf(0xfd.toByte())) }
        rejects { H264Config.parseAvcc(high + byteArrayOf(0xfd.toByte(), 0xf8.toByte(), 0xf8.toByte(), 1, 0, 0)) }
    }

    @Test fun completeMultiSliceAccessUnitIsConvertedForAllLengthSizes() {
        val nals = listOf(byteArrayOf(0x09, 0xf0.toByte()), slice(idr = true), slice(idr = true, firstMb = 50))
        val expected = annexB(nals)
        for (lengthSize in listOf(1, 2, 4)) {
            val payload = lengthPrefixed(nals, lengthSize)
            assertArrayEquals(expected, H264Config.toAnnexB(payload, lengthSize))
            val parsed = H264Config.parseAccessUnit(payload, lengthSize)
            assertTrue(parsed.isIdr)
            assertTrue(parsed.hasVcl)
            assertEquals(0, parsed.ppsId)
        }
    }

    @Test fun nonIdrAndParameterOnlyUnitsAreIdentified() {
        val dependent = H264Config.parseAccessUnit(lengthPrefixed(listOf(slice(idr = false)), 4), 4)
        assertFalse(dependent.isIdr)
        assertTrue(dependent.hasVcl)
        val parameterOnly = H264Config.parseAccessUnit(lengthPrefixed(listOf(sps(), pps()), 4), 4)
        assertFalse(parameterOnly.hasVcl)
        assertEquals(1, parameterOnly.sps.size)
        assertEquals(1, parameterOnly.pps.size)
    }

    @Test fun incompleteZeroAndUnsignedHugeNalLengthsAreRejected() {
        for (payload in listOf(byteArrayOf(), byteArrayOf(0, 0, 0), byteArrayOf(0, 0, 0, 0),
            byteArrayOf(-1, -1, -1, -1), byteArrayOf(0, 0, 0, 8, 0x65))) {
            rejects { H264Config.toAnnexB(payload, 4) }
        }
        rejects { H264Config.toAnnexB(lengthPrefixed(listOf(slice(true)), 4) + byteArrayOf(0), 4) }
    }

    @Test fun malformedAndUnsupportedNalHeadersAreRejected() {
        for (header in listOf(0, 0x80, 0x85, 0x05, 24, 0x62, 0x74)) {
            rejects { H264Config.toAnnexB(lengthPrefixed(listOf(byteArrayOf(header.toByte(), 0xff.toByte())), 4), 4) }
        }
        rejects { H264Config.toAnnexB(lengthPrefixed(listOf(byteArrayOf(0x65)), 4), 4) }
    }

    @Test fun slicesFromDifferentPicturesOrPpsAreRejected() {
        rejects { H264Config.toAnnexB(lengthPrefixed(listOf(slice(true), slice(false)), 4), 4) }
        rejects { H264Config.toAnnexB(lengthPrefixed(listOf(slice(true), slice(true, ppsId = 1)), 4), 4) }
    }

    @Test fun laterSliceAloneCannotBeARecoveryPoint() {
        rejects { H264Config.toAnnexB(lengthPrefixed(listOf(slice(true, firstMb = 50)), 4), 4) }
        rejects { H264Config.toAnnexB(lengthPrefixed(listOf(slice(false, firstMb = 50)), 4), 4) }
    }

    @Test fun pathologicalNalCountsAndByteSizesAreRejected() {
        val manyNals = lengthPrefixed(List(4097) { byteArrayOf(0x0c, 0xff.toByte()) }, 1)
        rejects { H264Config.toAnnexB(manyNals, 1) }
        rejects { H264Config.toAnnexB(ByteArray(H264Config.MAX_ACCESS_UNIT_BYTES + 1), 4) }
        rejects { H264Config.toAnnexB(byteArrayOf(1, 0x0c), 3) }
    }

    @Test fun parameterSetCsdIsAnnexBWithEverySetRetained() {
        val nals = listOf(sps(id = 0), sps(id = 1))
        assertArrayEquals(annexB(nals), H264Config.parameterSetsToAnnexB(nals))
        rejects { H264Config.parameterSetsToAnnexB(emptyList()) }
        rejects { H264Config.parameterSetsToAnnexB(listOf(byteArrayOf())) }
    }

    @Test fun inBandUpdatesReplaceSameIdButRetainOtherSets() {
        val config = H264Config.fromParameterSets(listOf(sps(id = 0), sps(id = 1)), listOf(pps(), pps(id = 1, spsId = 1)))
        val changed = sps(id = 1, widthMbs = 80, heightMapUnits = 45)
        val unit = H264Config.parseAccessUnit(lengthPrefixed(listOf(changed, pps(id = 1, spsId = 1), slice(true, ppsId = 1)), 4), 4)
        val updated = H264Config.mergeParameterSets(config, unit)
        assertEquals(1280, updated.width)
        assertEquals(720, updated.height)
        assertEquals(2, updated.sps.size)
        assertEquals(2, updated.pps.size)
        assertArrayEquals(changed, updated.sps[1])
    }

    @Test fun activeSlicePpsSelectsExistingSpsWithoutInBandUpdates() {
        val config = H264Config.fromParameterSets(listOf(sps(id = 0), sps(id = 1, widthMbs = 80)),
            listOf(pps(), pps(id = 3, spsId = 1)))
        val unit = H264Config.parseAccessUnit(lengthPrefixed(listOf(slice(true, ppsId = 3)), 4), 4)
        assertEquals(1280, H264Config.mergeParameterSets(config, unit).width)
        val unknown = H264Config.parseAccessUnit(lengthPrefixed(listOf(slice(true, ppsId = 7)), 4), 4)
        rejects { H264Config.mergeParameterSets(config, unknown) }
    }

    @Test fun randomMalformedInputsHaveOnlyControlledParseFailures() {
        val random = Random(0x264L)
        repeat(2000) {
            val bytes = ByteArray(random.nextInt(256)).also { random.nextBytes(it) }
            try { H264Config.parseAvcc(bytes) } catch (_: IllegalArgumentException) { }
            try { H264Config.parseSps(bytes) } catch (_: IllegalArgumentException) { }
            try { H264Config.toAnnexB(bytes, listOf(1, 2, 4)[it % 3]) } catch (_: IllegalArgumentException) { }
        }
    }

    private fun rejects(block: () -> Any?) {
        try { block() } catch (_: IllegalArgumentException) { return }
        fail("Expected IllegalArgumentException")
    }

    private fun hex(value: String): ByteArray = value.chunked(2).map { it.toInt(16).toByte() }.toByteArray()

    private fun sps(
        id: Int = 0, profile: Int = 66, chroma: Int = 1, separatePlane: Boolean = false,
        widthMbs: Int = 40, heightMapUnits: Int = 30, frameOnly: Boolean = true,
        cropLeft: Int = 0, cropRight: Int = 0, cropTop: Int = 0, cropBottom: Int = 0,
        scalingMatrix: Boolean = false, pocType: Int = 0, vui: Boolean = false,
    ): ByteArray {
        val b = Bits()
        b.fixed(profile, 8); b.fixed(0, 8); b.fixed(40, 8); b.ue(id)
        if (profile != 66) {
            b.ue(chroma)
            if (chroma == 3) b.flag(separatePlane)
            b.ue(0); b.ue(0); b.flag(false); b.flag(scalingMatrix)
            if (scalingMatrix) repeat(if (chroma == 3) 12 else 8) {
                b.flag(it == 0)
                if (it == 0) b.se(-8)
            }
        }
        b.ue(0); b.ue(pocType)
        if (pocType == 0) b.ue(0)
        if (pocType == 1) { b.flag(false); b.se(-1); b.se(1); b.ue(2); b.se(-2); b.se(2) }
        b.ue(1); b.flag(false); b.ue(widthMbs - 1); b.ue(heightMapUnits - 1)
        b.flag(frameOnly)
        if (!frameOnly) b.flag(false)
        b.flag(true)
        val crop = cropLeft != 0 || cropRight != 0 || cropTop != 0 || cropBottom != 0
        b.flag(crop)
        if (crop) { b.ue(cropLeft); b.ue(cropRight); b.ue(cropTop); b.ue(cropBottom) }
        b.flag(vui)
        if (vui) {
            b.flag(true); b.fixed(255, 8); b.fixed(1, 16); b.fixed(1, 16)
            b.flag(false); b.flag(false); b.flag(false)
            b.flag(true); b.fixed(1, 32); b.fixed(60, 32); b.flag(true)
            b.flag(true); b.ue(0); b.fixed(0, 4); b.fixed(0, 4)
            b.ue(1); b.ue(1); b.flag(false)
            repeat(4) { b.fixed(23, 5) }
            b.flag(false); b.flag(false); b.flag(false)
            b.flag(true); b.flag(true)
            repeat(6) { b.ue(0) }
        }
        return escapeNal(0x67, b.finish())
    }

    private fun pps(id: Int = 0, spsId: Int = 0): ByteArray {
        val b = Bits()
        b.ue(id); b.ue(spsId); b.flag(false); b.flag(false)
        b.ue(0); b.ue(0); b.ue(0); b.flag(false); b.fixed(0, 2)
        b.se(0); b.se(0); b.se(0); b.flag(true); b.flag(false); b.flag(false)
        return escapeNal(0x68, b.finish())
    }

    private fun slice(idr: Boolean, firstMb: Int = 0, ppsId: Int = 0): ByteArray {
        val b = Bits()
        b.ue(firstMb); b.ue(if (idr) 2 else 0); b.ue(ppsId)
        b.fixed(0, 4)
        if (idr) b.ue(0)
        return escapeNal(if (idr) 0x65 else 0x41, b.finish())
    }

    private fun avcc(sps: List<ByteArray> = listOf(sps()), pps: List<ByteArray> = listOf(pps()), lengthSize: Int = 4): ByteArray {
        val out = ByteArrayOutputStream()
        out.write(byteArrayOf(1, sps.firstOrNull()?.get(1) ?: 66, 0, 40, (0xfc or (lengthSize - 1)).toByte(), (0xe0 or sps.size).toByte()))
        sps.forEach { out.write(it.size ushr 8); out.write(it.size); out.write(it) }
        out.write(pps.size)
        pps.forEach { out.write(it.size ushr 8); out.write(it.size); out.write(it) }
        return out.toByteArray()
    }

    private fun lengthPrefixed(nals: List<ByteArray>, lengthSize: Int): ByteArray {
        val out = ByteArrayOutputStream()
        nals.forEach { nal ->
            for (i in lengthSize - 1 downTo 0) out.write(nal.size ushr (i * 8))
            out.write(nal)
        }
        return out.toByteArray()
    }

    private fun annexB(nals: List<ByteArray>): ByteArray {
        val out = ByteArrayOutputStream()
        nals.forEach { out.write(byteArrayOf(0, 0, 0, 1)); out.write(it) }
        return out.toByteArray()
    }

    private fun escapeNal(header: Int, rbsp: ByteArray): ByteArray {
        val out = ByteArrayOutputStream()
        out.write(header)
        var zeros = 0
        rbsp.forEach {
            val value = it.toInt() and 0xff
            if (zeros >= 2 && value <= 3) { out.write(3); zeros = 0 }
            out.write(value)
            zeros = if (value == 0) zeros + 1 else 0
        }
        return out.toByteArray()
    }

    private class Bits {
        private val bits = ArrayList<Int>()
        fun fixed(value: Int, count: Int) { for (i in count - 1 downTo 0) bits.add((value ushr i) and 1) }
        fun flag(value: Boolean) { bits.add(if (value) 1 else 0) }
        fun ue(value: Int) {
            val code = value + 1
            val width = 32 - Integer.numberOfLeadingZeros(code)
            repeat(width - 1) { bits.add(0) }
            fixed(code, width)
        }
        fun se(value: Int) = ue(if (value <= 0) -value * 2 else value * 2 - 1)
        fun finish(): ByteArray {
            bits.add(1)
            while (bits.size % 8 != 0) bits.add(0)
            return ByteArray(bits.size / 8) { index ->
                var value = 0
                repeat(8) { value = (value shl 1) or bits[index * 8 + it] }
                value.toByte()
            }
        }
    }
}
